{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Glimepiride, the closest analogue sharing the arylsulfonylurea core and phenethyl linker, had an absolute oral bioavailability of 97% in healthy male volunteers when measured against IV dosing, strongly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "PF-05150122, a sulfonylurea-containing analogue, showed 52% absolute oral bioavailability in humans after oral versus IV administration, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Bosentan, a sulfonamide-containing oral drug with moderate lipophilicity, had approximately 50% absolute oral bioavailability in healthy subjects, supporting the high-F prediction for this chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of glimepiride, whose absolute oral bioavailability is near 100% in humans. Additional sulfonylurea/sulfonamide-containing analogues with high transfer scores also show F values of roughly 50%, all above the 20% threshold. Lower-transfer low-F molecules are structurally distant and do not override this consistent high-bioavailability evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "Low-oral-bioavailability evidence comes from structurally distant molecules with lower transfer scores and is not mechanistically transferable to the glimepiride-like sulfonylurea scaffold.",
    "Formulation-dependent effects on absorption for the query are not directly addressed by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

